head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.pageNoCnt = 10; // page 번호 개수
scwin.vCurrPageNo = 0; // 현재 선택된 페이지번호
scwin.vPAGENO = 0;
scwin.reqKsdIsuRegDD = "";
scwin.procJob = "발행등록요청";
scwin.gIsurCd;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {void}
 * @hidden N
 */
scwin.onpageload = function() {
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

/**
 * @method
 * @name init
 * @description 화면 초기화 — 파라미터 수신·기본값·컴포넌트 초기 설정(onpageload 에서 순차 호출)
 * @returns {void}
 * @hidden N
 */
scwin.init = function() {
    // 한달전 날짜 : 20081110: 허기영 요구사항
    const vCurDate = $c.ut.cGetToday("yyyymmdd");
    edt_SDATE.setValue($c.ut.cGetMinusDate2(vCurDate, 7)); // 일주일전 날짜
    edt_EDATE.setValue($c.ut.cGetToday("yyyymmdd")); // 현재날짜
    edt_FromDt.setValue($c.ut.cGetToday("yyyymmdd")); // 현재날짜
    edt_ToDt.setValue($c.ut.cGetToday("yyyymmdd")); // 현재날짜

    const h = "FROM_DT:string,TO_DT:string";

    dts_List.SetDataHeader(h);
    if (js_market !== "9") {
        panel_mkt.hide();
    }
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_Search_onclick
 * @description 「조회」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Search_onclick = async function(e) {
    try {
        await scwin.listNewPassword();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF24800.btn_Search_onclick" });
    }
};

/**
 * @method
 * @name btn_SDATE_onclick
 * @description btn_SDATE 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_SDATE_onclick = function(e) {
    try {
        popUpCalendar2(edt_SDATE);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF24800.btn_SDATE_onclick" });
    }
};

/**
 * @method
