/**
 * @method
 * @name cmb_PeriodTp_onselchange
 * @description cmb_PeriodTp onselchange 이벤트
 * @param {Object} info 이벤트 정보 객체
 * @returns {void}
 * @hidden N
 */
scwin.cmb_PeriodTp_onselchange = function(info) {
    try {
        const vTp = cmb_PeriodTp.getValue();
        $c.stf.setFromToDate(vTp, edt_SDATE, edt_EDATE);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF24800.cmb_PeriodTp_onselchange" });
    }
};

/**
 * @method
 * @name btn_Excel_onclick
 * @description 「엑셀다운로드」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_Excel_onclick = function(e) {
    try {
        $c.stf.doLogSave("ULDSTF24800.gfm", SCREN_PROCS_TP_CD_07, '');
        $c.data.downloadGridViewExcel(grd_Grid, {fileName: "예탁원발행정보 목록", type: "8"});
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF24800.btn_Excel_onclick" });
    }
};

/**
 * @method
 * @name cmb_PerPage_onselchange
 * @description cmb_PerPage onselchange 이벤트
 * @param {Object} info 이벤트 정보 객체
 * @returns {void}
 * @hidden N
 */
scwin.cmb_PerPage_onselchange = function(info) {
    try {
        scwin.vCurrPageNo = 1;
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF24800.cmb_PerPage_onselchange" });
    }
};

/**
 * @method
 * @name dts_CORP_USR_TP_CD_OnLoadCompleted
 * @description dts_CORP_USR_TP_CD 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.dts_CORP_USR_TP_CD_OnLoadCompleted = function(e) {
    try {
        // 채권상장신청자 제거
        dts_CORP_USR_TP_CD.setBroadcast(false);
        for (let i = 1; i <= dts_CORP_USR_TP_CD.getRowCount(); i++) {
            if (dts_CORP_USR_TP_CD.getCellData(i, "VALUE") === "71") {
                dts_CORP_USR_TP_CD.removeRow(i + 1);
                break;
            }
        }
        dts_CORP_USR_TP_CD.setBroadcast(true, true);
        cmb_KSD_ISU_ERAS_TP_CD.setValue('');
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF24800.dts_CORP_USR_TP_CD_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name dts_PassList_OnLoadCompleted
 * @description dts_PassList 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.dts_PassList_OnLoadCompleted = function(e) {
    try {
        if (scwin.vPAGENO === 0) {
            scwin.vCurrPageNo = 1;
            // alert("vPAGENO == 0");

        }
        const vTotalCnt = dts_PassList.getCellData(1, "CNT");
        // alert("vTotalCnt=" + vTotalCnt);
        // alert(getObjectValue(cmb_PerPage));
        $c.stf.FillGridHeader2(scwin.pageNoCnt, cmb_PerPage.getValue(), vTotalCnt, panel_page);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF24800.dts_PassList_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name dts_PassList_OnLoadError
 * @description dts_PassList 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_PassList_OnLoadError = async function(e) {
    try {
        await $c.win.alert(dts_PassList);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF24800.dts_PassList_OnLoadError" });
    }
};

/**
 * @method
 * @name grd_Grid_OnDblClick
 * @description grd_Grid 더블클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
