/**
 * @method
 * @name listNewPassword
 * @description list New Password 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.listNewPassword = async function() {
    const argv = scwin.listNewPassword.arguments;
    const argc = scwin.listNewPassword.arguments.length;
    scwin.vPAGENO = (argc === 0) ? 0 : scwin.vPAGENO = argv[0];
    let lPageNo = 0;
    if (scwin.vPAGENO === 0) {
        lPageNo = 1;
    } else {
        lPageNo = scwin.vPAGENO;
    }
    let secuGrpId = "";
    if (chb_Grp_ST_21.getValue() === 'Y') secuGrpId += '21,';
    if (chb_Grp_DR_51.getValue() === 'Y') secuGrpId += '51,';
    if (chb_Grp_SR_22.getValue() === 'Y') secuGrpId += '22,';
    if (chb_Grp_SW_23.getValue() === 'Y') secuGrpId += '23,';
    if (chb_Grp_BC_31.getValue() === 'Y') secuGrpId += 'BC,';
    if (chb_Grp_BND_11.getValue() === 'Y') secuGrpId += '11,';
    if (chb_Grp_EF_31.getValue() === 'Y') secuGrpId += 'EF,';
    if (chb_Grp_EN_44.getValue() === 'Y') secuGrpId += '44,';
    if (chb_Grp_EW_42.getValue() === 'Y') secuGrpId += '42,';
    if (chb_Grp_EW_42.getValue() === 'Y') secuGrpId += '42,';
    if (chb_Grp_IC_61.getValue() === 'Y') secuGrpId += '61,';
    if (chb_Grp_TC_32.getValue() === 'Y') secuGrpId += '32,';
    if (chb_Grp_PF_31.getValue() === 'Y') secuGrpId += 'PF,';
    if (chb_Grp_All.getValue() === 'Y') secuGrpId = '';
    // alert("vPAGENO="+vPAGENO);
    // alert("lPageNo="+lPageNo);
    // alert("lPageSize="+getObjectValue(cmb_PerPage));

    url += "&{P}V_ISU_KOR_NM=" + txb_ISUR_NM.getValue();
    url += "&{P}V_SECUGRP_ID=" + secuGrpId;
    url += "&{P}V_SPOT_ISU_TRD_MKT_TP_CD=" + rdo_SPOT_ISU_TRD_MKT_TP_CD.getValue();
    url += "&{P}V_KSD_ISU_ERAS_TP_CD=" + cmb_KSD_ISU_ERAS_TP_CD.getValue();
    url += "&{P}V_SDATE=" + edt_SDATE.getValue();
    url += "&{P}V_EDATE=" + edt_EDATE.getValue();
    url += "&{P}V_lPageNo=" + lPageNo;
    url += "&{P}V_lPageSize=" + cmb_PerPage.getValue();
    // alert(url);
    const sbmOptions = {
        id : "sbm_dts_PassList",
        action : "/listingCommon.do",
        ref : "",
        target : "dts_PassList=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

