/**
 * @method
 * @name allCheck
 * @description all Check 처리
 * @returns {void}
 * @hidden N
 */
scwin.allCheck = function() {
    const checkArray = [chb_Grp_ST_21, chb_Grp_DR_51, chb_Grp_SR_22, chb_Grp_SW_23, chb_Grp_BC_31, chb_Grp_BND_11, chb_Grp_EF_31, chb_Grp_EN_44, chb_Grp_EW_42, chb_Grp_IC_61, chb_Grp_TC_32, chb_Grp_PF_31];
    if (chb_Grp_All.checked === true) {
        for (let i = 0; i < checkArray.length; i++) {
            checkArray[i].checked = 0;
        }
    }
};

