/**
 * @method
 * @name restrictDuration
 * @description restrict Duration 처리
 * @returns {void}
 * @hidden N
 */
scwin.restrictDuration = function() {
    const duration = 6;
    const start = edt_FromDt.getValue();
    const end = edt_ToDt.getValue();
    const startDate = new Date();
    const endDate = new Date();
    startDate.setYear(start.substring(0, 4));
    startDate.setMonth(start.substring(4, 6));
    startDate.setDate(start.substring(6, 8));
    endDate.setYear(end.substring(0, 4));
    endDate.setMonth(end.substring(4, 6));
    endDate.setDate(end.substring(6, 8));
    const diffTime = endDate.getTime() - startDate.getTime();
    const diffDays = diffTime / (1000 * 60 * 60 * 24);
    if (diffDays > duration) {
        const msg = " 조회기간은 7일 이하로 제한됩니다.";
        alert(msg);
        return false;
    }
    return true;
};

